import{_ as t,o as n,c as i,a3 as r}from"./chunks/framework.z_KJ15Ep.js";const m=JSON.parse('{"title":"Text-, CSV- und Tabellendateien bearbeiten","description":"","frontmatter":{"title":"Text-, CSV- und Tabellendateien bearbeiten","source_pageid":1382,"source_revision":5209},"headers":[],"relativePath":"schild3/schueler/weitere-programme-fuer-dateioperationen-tipps.md","filePath":"schild3/schueler/weitere-programme-fuer-dateioperationen-tipps.md"}'),a={name:"schild3/schueler/weitere-programme-fuer-dateioperationen-tipps.md"};function o(l,e,s,d,p,u){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="text-csv-und-tabellendateien-bearbeiten" tabindex="-1">Text-, CSV- und Tabellendateien bearbeiten <a class="header-anchor" href="#text-csv-und-tabellendateien-bearbeiten" aria-label="Permalink to &quot;Text-, CSV- und Tabellendateien bearbeiten&quot;">​</a></h1><p>Nutzen Sie Tabellenkalkulation oder Texteditor für Import-, Export- und Schnittstellendateien. Der Artikel nennt Einsatzmöglichkeiten für Bearbeitung und Auswertung.</p><p>Text- und CSV-Dateien aus Im- und Exporten können Sie mit einem Tabellenkalkulationsprogramm öffnen, zum Beispiel OpenOffice Calc oder Microsoft Excel. <strong>CSV</strong> bezeichnet eine Textdatei, in der die Spalten durch Trennzeichen getrennt sind. Wie Sie eine solche Datei öffnen, hängt vom verwendeten Programm ab.</p><p>Auch reine Texteditoren können bei der Arbeit mit den Textdateien nützlich sein. Das bei Windows mitgelieferte <em>Notepad</em> ist oft schon ausreichend, <em>Notepad++</em> bringt weitaus umfassendere Features mit.</p><p>Zur Auswertung der Daten lohnt sich ein Blick auf die Diagramm- und Statistikfunktionen der Tabellenkalkulationsprogramme. Auch ein Blick auf Pivot-Tables kann hier neue Möglichkeiten eröffnen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Weitere_Programme_f%C3%BCr_Dateioperationen_(Tipps)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5209.</p>',7)])])}const h=t(a,[["render",o]]);export{m as __pageData,h as default};
